const formatResponse = (text) => {
    if (!text) return null;

    const lines = text.split("\n");

    return lines.map((line, index) => {
      const trimmed = line.trim();

      if (!trimmed) {
        return <div key={index} className="answer-space" />;
      }

      // Bullet points
      if (trimmed.startsWith("* ")) {
        return (
          <div className="answer-bullet" key={index}>
            <span className="bullet-dot">•</span>
            <span>{trimmed.substring(2)}</span>
          </div>
        );
      }

      // Numbered points
      if (/^\d+\.\s/.test(trimmed)) {
        const match = trimmed.match(/^(\d+)\.\s(.*)$/);

        return (
          <div className="answer-numbered" key={index}>
            <span className="number-badge">{match[1]}</span>
            <span>{match[2]}</span>
          </div>
        );
      }

      // Source line
      if (trimmed.startsWith("Source:")) {
        return (
          <div className="answer-source-line" key={index}>
            {trimmed}
          </div>
        );
      }

      return (
        <p className="answer-paragraph" key={index}>
          {trimmed}
        </p>
      );
    });
  };

  const detectedDisaster =
    sources.length > 0 && sources[0].disaster
      ? sources[0].disaster
      : null;

  return (
    <div className="app">
      <header className="header">
        <div className="brand">
          <div className="brand-icon">🌪️</div>

          <div>
            <h1>DisasterRelief AI</h1>
            <p>Evidence-Grounded Relief Assistance Navigator</p>
          </div>
        </div>

        <div className="header-status">
          <span className="status-dot"></span>
          Knowledge-Grounded
        </div>
      </header>

      <main className="main">
        <section className="hero">
          <div className="hero-badge">
            AI-POWERED DISASTER ASSISTANCE
          </div>

          <h2>Tell us what happened.</h2>

          <p className="hero-description">
            Describe your disaster-related situation in your own words.
            DisasterRelief AI retrieves relevant information from its
            knowledge base and provides an evidence-grounded response.
          </p>

          <div className="input-card">
            <div className="input-label-row">
              <label htmlFor="situation">
                Describe your situation
              </label>

              <span className="shortcut">
                ⌘ + Enter
              </span>
            </div>

            <textarea
              id="situation"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Example: My house was damaged by a flood. What assistance may be relevant?"
              rows="6"
            />

            <button
              onClick={analyzeSituation}
              disabled={loading || !message.trim()}
            >
              {loading ? (
                <>
                  <span className="spinner"></span>
                  Analyzing knowledge base...
                </>
              ) : (
                <>
                  Analyze My Situation
                  <span className="button-arrow">→</span>
                </>
              )}
            </button>
          </div>

          <div className="examples">
            <p>Try an example</p>

            <div className="example-list">
              <button
                className="example-button"
                onClick={() =>
                  setMessage(
                    "My house was damaged by a flood. What assistance may be relevant?"
                  )
                }
              >
                🌊 Flood + House Damage
              </button>

              <button
                className="example-button"
                onClick={() =>
                  setMessage(
                    "A cyclone damaged the roof of my house. What assistance should I look into?"
                  )
                }
              >
                🌀 Cyclone + House Damage
              </button>

              <button
                className="example-button"
                onClick={() =>
                  setMessage(
                    "My house suffered major damage after an earthquake. What should I do?"
                  )
                }
              >
                🏚️ Earthquake + House Damage
              </button>
            </div>
          </div>
        </section>

        {response && (
          <section className="response-section">
            <div className="section-title-row">
              <div>
                <div className="section-label">AI RESPONSE</div>
                <h3>Evidence-grounded analysis</h3>
              </div>

              {detectedDisaster && (
                <div className="disaster-badge">
                  <span>
                    {getDisasterIcon(detectedDisaster)}
                  </span>

                  <div>
                    <small>DETECTED DISASTER</small>
                    <strong>
                      {detectedDisaster.toUpperCase()}
                    </strong>
                  </div>
                </div>
              )}
            </div>

            <div className="response-card">
              <div className="answer-icon">✦</div>

              <div className="answer-content">
                {formatResponse(response)}
              </div>
            </div>

            {sources.length > 0 && (
              <div className="sources-card">
                <div className="sources-header">
                  <div>
                    <div className="section-label">
                      EVIDENCE
                    </div>

                    <h3>Retrieved Sources</h3>
                  </div>

                  <span className="source-count">
                    {sources.length} retrieved
                  </span>
                </div>

                <div className="source-list">
                  {sources.map((source, index) => (
                    <div className="source-item" key={index}>
                      <div className="source-number">
                        {String(index + 1).padStart(2, "0")}
                      </div>

                      <div className="source-content">
                        <strong>{source.document}</strong>

                        <div className="source-meta">
                          <span>{source.authority}</span>

                          <span className="meta-dot">•</span>

                          <span className="disaster-text">
                            {getDisasterIcon(source.disaster)}{" "}
                            {source.disaster}
                          </span>

                          <span className="meta-dot">•</span>

                          <span>
                            Page
                            {source.pages.length > 1 ? "s" : ""}:{" "}
                            {source.pages.join(", ")}
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="source-note">
                  <span>ⓘ</span>
                  Responses are generated only from the retrieved
                  knowledge-base content.
                </div>
              </div>
            )}
          </section>
        )}
      </main>

      <footer>
        <p>
          DisasterRelief AI
          <span>•</span>
          Evidence-Grounded Disaster Assistance
          <span>•</span>
          Knowledge Base
        </p>
      </footer>
    </div>
  );
}

export default App;
