def ask_codellama_without_rag(question):

    prompt = f"""
Answer the following question.

Question:
{question}

Answer:
"""

    response = requests.post(
        OLLAMA_GENERATE_URL,
        json={
            "model": LLM_MODEL,
            "prompt": prompt,
            "stream": False,
            "options": {
                "temperature": 0.1
            }
        },
        timeout=180
    )

    response.raise_for_status()

    return response.json()["response"].strip()
