const analyzeSituation = async () => {
    if (!message.trim()) {
      return;
    }

    setLoading(true);
    setResponse("");
    setSources([]);

    try {
      const result = await fetch("http://127.0.0.1:8000/api/chat", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          message: message.trim(),
        }),
      });

      if (!result.ok) {
        throw new Error("Failed to get response from server");
      }

      const data = await result.json();

      setResponse(data.response || "");
      setSources(data.sources || []);
    } catch (error) {
      setResponse(
        "Unable to connect to the DisasterRelief AI server. Please make sure the backend is running."
      );
      setSources([]);
    } finally {
      setLoading(false);
    }
  };

