const getDisasterIcon = (disaster) => {
    if (!disaster) return "📚";

    const value = disaster.toLowerCase();

    if (value === "flood") return "🌊";
    if (value === "cyclone") return "🌀";
    if (value === "earthquake") return "🏚️";

    return "⚠️";
  };

